<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
requireStaff();
$pdo=getDatabaseConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!validCsrfToken($_POST['csrf_token']??null))$error='Your session expired.';
    else{$foundId=filter_input(INPUT_POST,'found_id',FILTER_VALIDATE_INT);$storage=trim((string)($_POST['storage_location']??''));if(!$foundId)$error='Invalid item.';else{$statement=$pdo->prepare('UPDATE found_items SET storage_location=:storage WHERE found_id=:id');$statement->execute(['storage'=>$storage?:null,'id'=>$foundId]);$message='Storage location updated successfully.';}}
}
$items=$pdo->query("SELECT f.found_id,f.item_name,f.storage_location,f.status,f.found_date,c.category_name,b.building_name,u.name finder_name FROM found_items f JOIN categories c ON c.category_id=f.category_id JOIN users u ON u.user_id=f.finder_id LEFT JOIN buildings b ON b.building_id=f.building_id WHERE f.status NOT IN ('closed','rejected') ORDER BY f.created_at DESC")->fetchAll();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Physical Inventory</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand brand-with-mark" href="../dashboard.php"><span class="brand-mark">LU</span>Liwa University Lost & Found</a><nav><a href="reports.php">Reports</a><a href="claims.php">Claims</a><a href="returns.php">Returns</a><a href="../dashboard.php">Dashboard</a></nav></header><main class="admin-page"><p class="eyebrow">Physical item management</p><h1>Found Item Inventory</h1><p class="form-intro">Record the cabinet, shelf, office, or other physical storage location.</p><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-error"><?=e($error)?></div><?php endif;?><?php if(!$items):?><div class="empty-state">No active found items.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>ID</th><th>Item</th><th>Category</th><th>Found at</th><th>Finder</th><th>Status</th><th>Physical storage</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td>#<?=(int)$item['found_id']?></td><td><?=e($item['item_name'])?></td><td><?=e($item['category_name'])?></td><td><?=e($item['building_name']??'-')?> · <?=e($item['found_date'])?></td><td><?=e($item['finder_name'])?></td><td><span class="status status-<?=e($item['status'])?>"><?=e(ucwords(str_replace('_',' ',$item['status'])))?></span></td><td><form class="storage-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="found_id" value="<?=(int)$item['found_id']?>"><input name="storage_location" value="<?=e((string)$item['storage_location'])?>" placeholder="Cabinet / shelf / office"><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></body></html>
